using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerResource(UriTemplate = "config://app/settings",
    Name = "AppSettings",
    Description = "Returns the current application configuration data")]
public static class ConfigResource
{
    [ResourceFunction]
    public static string GetSettings()
    {
        // In production, load from IConfiguration or a database
        return """
        {
            "environment": "production",
            "maxRetries": 3,
            "timeoutSeconds": 30,
            "featureFlags": {
                "darkMode": true,
                "betaFeatures": false
            }
        }
        """;
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTool
{
    [McpServerTool(Name = "greet"), Description("Greets a user by name")]
    public static string Greet([Description("The name to greet")] string name)
    {
        return $"Hello, {name}! Welcome to the MCP HTTP server.";
    }
}

arguments.old_str:
var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/", () => "Hello World!");

app.Run();

